// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkProgramItem) predicate.WorkProgramItem {
	return predicate.WorkProgramItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkProgramItem) predicate.WorkProgramItem {
	return predicate.WorkProgramItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkProgramItem) predicate.WorkProgramItem {
	return predicate.WorkProgramItem(sql.NotPredicates(p))
}
